          file.operations.forEach(op => {
            if (op.type === 'crop') {
              this.imageProcessor.crop(op.x, op.y, op.width, op.height);
            }
          });
          this.imageProcessor.exportImage(file.outputPath, 'jpg');
          break;
      }
    });
  }
}

