class Book {
  constructor(
    public title: string,
    public author: string,
    public year: number,
    public genre: string
  ) {}

  toString(): string {
    return `"${this.title}" by ${this.author} (${this.year})`;
  }
}

class BookCollection implements Iterable<Book> {
  private books: Book[] = [];

  addBook(book: Book): void {
    this.books.push(book);
  }

