// Classic Module Pattern using IIFE
const CounterModule = (function() {
  // Private variables
  let count = 0;
  let history: number[] = [];

  // Private functions
  function log(action: string, value: number) {
    console.log(`[Counter] ${action}: ${value}`);
  }

  // Public API
  return {
    increment(): number {
      count++;
      history.push(count);
      log('increment', count);
      return count;
    },

    decrement(): number {
      count--;
      history.push(count);
      log('decrement', count);
      return count;
    },

    getCurrentValue(): number {
      return count;
    },

    getHistory(): readonly number[] {
      return [...history]; // Return copy to prevent external modification
    },

    reset(): void {
      count = 0;
      history = [];
      log('reset', count);
    }
  };
})();

// Factory function to create new instances
function createCounterInstance() {
  return CounterModule;
